let currentUser=null,allActivities=[],allMembers=[],departments=[],equipmentCategories=[],equipmentCategoriesFlat=[],allEquipment=[],allSocials=[],allArchives=[],scheduleWeekStart=null,sessionExpiredHandled=false;
const pageInfo={overview:['工作台总览','使命在肩，步履铿锵'],schedule:['活动课表','未来活动周安排'],forum:['队内论坛','实名交流与队务讨论'],time:['时间中心','日程提醒与操作记录'],activities:['活动项目','教官部 · 项目执行与考评'],equipment:['设备管理','后勤部 · 装备与物资保障'],office:['综合办公室','宣传、档案与素材审阅'],members:['队员名册','组织架构与成员信息'],governance:['组织审批','成员、部门与职务流程'],profile:['个人中心','查看与维护个人资料'],login:['身份认证','欢迎归队']};
const roleNames={member:'普通社员',minister:'部长',captain:'队长',admin:'管理员'};
const departmentLabel=u=>u?.department||((u?.roles||[]).includes('captain')?'队长直属':'未分部');
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const fmt=d=>d?new Date(d).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'待定';
const fmtFull=d=>d?new Date(d).toLocaleString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',weekday:'short',hour:'2-digit',minute:'2-digit'}):'未设置';
const localInput=d=>{if(!d)return'';const x=new Date(d),z=n=>String(n).padStart(2,'0');return `${x.getFullYear()}-${z(x.getMonth()+1)}-${z(x.getDate())}T${z(x.getHours())}:${z(x.getMinutes())}`};
const sizeText=b=>{const u=['B','KB','MB','GB'];let i=0,n=Number(b)||0;while(n>=1024&&i<u.length-1){n/=1024;i++}return `${n.toFixed(i?1:0)} ${u[i]}`};
const fileTypeLabel=t=>({image:'图片',video:'视频',audio:'音频',document:'文档',unknown:'文件'}[t]||'文件');
function showToast(msg){const e=document.getElementById('toast');e.textContent=msg;e.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>e.classList.remove('show'),2600)}
function toggleSidebar(){document.getElementById('sidebar').classList.toggle('open')}
function openModal(title,body,kicker='FORM'){document.getElementById('modalTitle').textContent=title;document.getElementById('modalKicker').textContent=kicker;document.getElementById('modalBody').innerHTML=`<div class="modal-body">${body}</div>`;document.getElementById('modalOverlay').classList.add('open')}
function closeModal(e){if(e&&e.target!==document.getElementById('modalOverlay'))return;document.getElementById('modalOverlay').classList.remove('open')}
function hasRole(r){return currentUser?.roles?.includes(r)}
function isManager(){return hasRole('minister')||hasRole('captain')||hasRole('admin')||(currentUser?.temporary_edit_departments||[]).length>0}
function isDept(name){return hasRole('captain')||hasRole('admin')||currentUser?.department===name||(currentUser?.temporary_edit_departments||[]).includes(name)}
/* 与后端 club.py 的 _can_department_edit(user, 部门名) 一一对应：
   队长、该部门部长、或持有该部门限时授权的社员。判断权限时一律走这个函数，
   避免各处各写一套、和后端不一致。 */
function canEditDepartment(name){return isManager()&&isDept(name)}
function renderAccess(){
  document.querySelectorAll('.manager-only').forEach(e=>e.classList.toggle('hidden',!isManager()));
  document.querySelectorAll('.instructor-only').forEach(e=>e.classList.toggle('hidden',!canEditDepartment('教官部')));
  document.querySelectorAll('.logistics-only').forEach(e=>e.classList.toggle('hidden',!canEditDepartment('后勤部')));
  document.querySelectorAll('.office-only').forEach(e=>e.classList.toggle('hidden',!canEditDepartment('综合办公室')));
  document.querySelectorAll('.captain-only').forEach(e=>e.classList.toggle('hidden',!(hasRole('captain')||hasRole('admin'))));
  document.querySelectorAll('.minister-or-captain').forEach(e=>e.classList.toggle('hidden',!(hasRole('minister')||hasRole('captain')||hasRole('admin'))));
  document.querySelectorAll('.member-only').forEach(e=>e.classList.toggle('hidden',hasRole('captain')||hasRole('admin')||hasRole('minister')));
  const logged=!!currentUser;document.getElementById('userChip').style.display=logged?'flex':'none';document.getElementById('loginSide').style.display=logged?'none':'block';
  if(logged){const name=currentUser.real_name||currentUser.username;document.getElementById('userName').textContent=name;document.getElementById('userAvatar').textContent=name.charAt(0);document.getElementById('userMeta').textContent=`${departmentLabel(currentUser)} · ${(currentUser.roles||[]).map(r=>roleNames[r]||r).join('/')}`}
}
async function showPage(name){
  if(document.querySelector(`[data-page="${name}"].protected`)&&!currentUser){showToast('请先登录工作台');name='login'}
  document.querySelectorAll('.page').forEach(e=>e.classList.remove('active'));document.getElementById('page-'+name)?.classList.add('active');
  document.querySelectorAll('.nav-item').forEach(e=>e.classList.toggle('active',e.dataset.page===name));
  document.getElementById('pageTitle').textContent=pageInfo[name]?.[0]||'';document.getElementById('pageSubtitle').textContent=pageInfo[name]?.[1]||'';
  document.getElementById('sidebar').classList.remove('open');
  if(name==='overview')loadOverview();if(name==='schedule')loadSchedule();if(name==='forum')loadForum();if(name==='time')loadTimeCenter();if(name==='activities')loadActivities();if(name==='equipment')loadEquipment();if(name==='office')loadOffice();if(name==='members')loadMembers();if(name==='governance')loadGovernance();if(name==='profile')loadProfile();
}
function quickEnter(){showPage(currentUser?'activities':'login')}
async function doLogin(){const err=document.getElementById('loginError');err.textContent='';const r=await API.login({username:document.getElementById('loginUsername').value.trim(),password:document.getElementById('loginPassword').value});if(r.status!==200){err.textContent=r.data.msg||'登录失败';return}localStorage.setItem('token',r.data.token);sessionExpiredHandled=false;currentUser=r.data.user;renderAccess();showToast('欢迎归队，'+(currentUser.real_name||currentUser.username));showPage('overview')}
function openRegistrationForm(){openModal('新社员注册申请',`<div class="modal-form"><label>用户名<input id="regUsername" placeholder="3—50 个字符"></label><label>真实姓名<input id="regRealName"></label><label>学号<input id="regStudentNo"></label><label>电子邮箱<input id="regEmail" type="email"></label><label class="wide">登录密码<input id="regPassword" type="password" placeholder="至少 6 位"></label><label class="wide">申请说明<textarea id="regReason" rows="3" placeholder="请简要说明入队情况"></textarea></label></div>${formActions('submitRegistration()','提交审核')}`,'MEMBER APPLICATION')}
async function submitRegistration(){const r=await API.register({username:regUsername.value.trim(),real_name:regRealName.value.trim(),student_no:regStudentNo.value.trim(),email:regEmail.value.trim(),password:regPassword.value,reason:regReason.value.trim()});showToast(r.data.msg||'提交完成');if(r.status===201)closeModal()}
function logout(){localStorage.removeItem('token');currentUser=null;renderAccess();showToast('已安全退出');showPage('overview')}
/* 令牌过期时由 api.js 回调。一个页面上往往有好几个并发请求同时收到 401，
   用 sessionExpiredHandled 去抖，避免弹好几次提示、跳好几次登录页。 */
function handleSessionExpired(){if(sessionExpiredHandled)return;sessionExpiredHandled=true;localStorage.removeItem('token');currentUser=null;closeModal();renderAccess();showPage('login');showToast('登录状态已过期，请重新登录');setTimeout(()=>{sessionExpiredHandled=false},2000)}
async function restoreSession(){if(!getToken())return renderAccess();const r=await API.profile();if(r.status===200)currentUser=r.data.user;else localStorage.removeItem('token');renderAccess()}
async function loadOverview(){if(!currentUser)return;const r=await API.overview();if(r.status!==200)return;const d=r.data;document.getElementById('overviewHint').textContent='数据更新于 '+new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'});document.getElementById('overviewStats').innerHTML=`<article class="stat"><span>在队成员</span><strong>${d.member_count}</strong><small>人</small></article><article class="stat"><span>活动项目</span><strong>${d.activity_count}</strong><small>项</small></article><article class="stat"><span>在库装备</span><strong>${d.equipment_count}</strong><small>件</small></article><article class="stat alert"><span>待办事项</span><strong>${d.active_borrows+d.pending_media}</strong><small>项</small></article>`;document.getElementById('dashboardLists').style.display='grid';document.getElementById('upcomingList').innerHTML=d.upcoming.length?d.upcoming.map(a=>`<div class="timeline-item"><div class="date"><b>${new Date(a.start_time).getDate()}</b><small>${new Date(a.start_time).getMonth()+1}月</small></div><div><h4>${esc(a.title)}</h4><p>${esc(a.location||'地点待定')} · 主教官 ${esc(a.lead_instructor_name)}</p></div><span class="tag">${esc(a.status)}</span></div>`).join(''):'<div class="empty">暂无近期活动</div>'}
async function loadSchedule(){if(!scheduleWeekStart){const n=new Date();n.setHours(0,0,0,0);n.setDate(n.getDate()-((n.getDay()+6)%7));scheduleWeekStart=n}const end=new Date(scheduleWeekStart);end.setDate(end.getDate()+7);const r=await API.schedule({start:localInput(scheduleWeekStart),end:localInput(end)});if(r.status!==200)return showToast(r.data.msg||'课表加载失败');document.getElementById('scheduleRange').textContent=`${scheduleWeekStart.getMonth()+1}月${scheduleWeekStart.getDate()}日 — ${end.getMonth()+1}月${end.getDate()-1}日`;const byDay=Array.from({length:7},()=>[]);(r.data.activities||[]).forEach(a=>{const i=Math.floor((new Date(a.start_time)-scheduleWeekStart)/86400000);if(i>=0&&i<7)byDay[i].push(a)});const weekdays=['周一','周二','周三','周四','周五','周六','周日'];document.getElementById('weekGrid').innerHTML=byDay.map((rows,i)=>{const date=new Date(scheduleWeekStart);date.setDate(date.getDate()+i);return `<section class="week-day"><header><b>${weekdays[i]}</b><span>${date.getMonth()+1}/${date.getDate()}</span></header><div>${rows.length?rows.map(a=>`<button class="schedule-card" onclick="openActivity(${a.activity_id})"><time>${new Date(a.start_time).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}</time><strong>${esc(a.title)}</strong><small>${esc(a.activity_type)} · ${esc(a.location||'待定')}</small><em>+${a.participation_points} 积分</em></button>`).join(''):'<p class="day-empty">暂无安排</p>'}</div></section>`}).join('')}
function changeScheduleWeek(step){scheduleWeekStart.setDate(scheduleWeekStart.getDate()+step*7);loadSchedule()}
async function loadTimeCenter(){const startEl=document.getElementById('timeStart'),endEl=document.getElementById('timeEnd');if(!startEl.value){const now=new Date(),later=new Date(now);later.setDate(now.getDate()+30);startEl.value=now.toISOString().slice(0,10);endEl.value=later.toISOString().slice(0,10)}const params={start:startEl.value+'T00:00:00',end:endEl.value+'T23:59:59'},recordParams={...params,limit:100};const moduleValue=document.getElementById('timeModule').value;if(moduleValue)recordParams.module=moduleValue;const [schedule,records]=await Promise.all([API.timeOverview(params),API.timeRecords(recordParams)]);if(schedule.status!==200)return showToast(schedule.data.msg||'时间数据加载失败');const d=schedule.data;document.getElementById('timeStats').innerHTML=`<div class="mini-stat"><strong>${d.activity_count}</strong><span>范围内活动</span></div><div class="mini-stat"><strong>${d.return_due_count}</strong><span>设备应归还</span></div><div class="mini-stat"><strong>${d.pending_media_count}</strong><span>素材待审阅</span></div><div class="mini-stat alert-mini"><strong>${d.overdue_count}</strong><span>已超期事项</span></div>`;const moduleLabel={activity:'活动',equipment:'设备',media:'素材',archive:'档案',office:'办公室'};document.getElementById('scheduleTimeline').innerHTML=d.events.length?d.events.map(x=>`<div class="schedule-item ${x.is_overdue?'overdue':''}"><div class="schedule-date"><b>${new Date(x.time).getDate()}</b><small>${new Date(x.time).getMonth()+1}月</small></div><div class="grow"><div><span class="tag ${x.is_overdue?'red':''}">${esc(x.event_type)}</span><small>${fmtFull(x.time)}</small></div><h4>${esc(x.title)}</h4><p>${esc(x.detail||'')} · ${esc(x.status||'')}</p></div></div>`).join(''):'<div class="empty">所选时间范围内暂无日程</div>';const rows=records.data?.records||[];document.getElementById('operationTimeline').innerHTML=rows.length?rows.map(x=>`<div class="operation-item"><i class="module-${esc(x.module)}"></i><div class="grow"><div><b>${esc(x.action)}</b><span>${esc(moduleLabel[x.module]||x.module)}</span></div><h4>${esc(x.target_name||x.target_type)}</h4><p>${esc(x.operator_name)} · ${esc(x.detail||'')}</p><time>${fmtFull(x.occurred_at)}</time></div></div>`).join(''):'<div class="empty">所选条件下暂无操作记录</div>'}
async function loadActivities(status=''){const r=await API.activities(status);if(r.status!==200)return showToast(r.data.msg);allActivities=r.data.activities;document.getElementById('activityCount').textContent=`${allActivities.length} 个项目`;document.getElementById('activityList').innerHTML=allActivities.length?allActivities.map(a=>`<article class="activity-card">${a.cover_url?`<img class="activity-cover" src="${esc(a.cover_url)}" alt="${esc(a.title)}">`:`<div class="activity-cover placeholder">旗</div>`}<div class="activity-card-body"><div class="card-top"><span class="activity-type">${esc(a.activity_type)}</span><span class="status">● ${esc(a.status)}</span></div><h3>${esc(a.title)}</h3><p>${esc(a.description||'暂无活动说明')}</p><div class="activity-meta"><div>活动时间<b>${fmt(a.start_time)}</b></div><div>签到窗口<b>${fmt(a.checkin_start)}—${fmt(a.checkin_end)}</b></div><div>活动主教官<b>${esc(a.lead_instructor_name)}</b></div><div>参与积分<b>+${a.participation_points} 分 · ${a.present_count}/${a.participant_count} 已到</b></div></div><div class="card-actions"><button onclick="openActivity(${a.activity_id})">查看与管理</button><button class="checkin-btn" onclick="checkInActivity(${a.activity_id})">立即打卡</button></div></div></article>`).join(''):'<div class="empty">暂无符合条件的活动项目</div>'}
function filterActivities(status,btn){document.querySelectorAll('.tabs button').forEach(e=>e.classList.remove('active'));btn.classList.add('active');loadActivities(status)}
function formActions(action,label='保存'){return `<div class="modal-foot"><button class="small-btn" onclick="closeModal()">取消</button><button class="btn primary" onclick="${action}">${label}</button></div>`}
/* ── 通用文件选择器：可当场上传，也可从「我的文件」里挑一个 ───────────────── */
let pickedFile=null,filePickerCallback=null,filePickerList=[];
async function openFilePicker(title,onPicked){filePickerCallback=onPicked;pickedFile=null;const r=await API.myFiles();filePickerList=r.status===200?r.data.files:[];openModal(title,`<div class="modal-form"><label class="wide upload-field">上传新文件<input id="fpFile" type="file"><small>支持图片、音视频、PDF、Office 文档与 zip；中文名可正常保留</small></label><label>可见范围<select id="fpVisibility"><option value="1">公开（全队可见）</option><option value="0">私有（仅自己）</option><option value="2">授权可见</option></select></label><label>文件说明<input id="fpDesc" placeholder="选填"></label></div><div class="picker-actions"><button class="small-btn" onclick="submitFileUpload()">上传到文件库</button></div><h4>我的文件</h4><div class="picker-list" id="fpList"></div>${formActions('confirmFilePick()','选用该文件')}`,'FILE LIBRARY');renderFilePicker()}
function renderFilePicker(){const el=document.getElementById('fpList');if(!el)return;el.innerHTML=filePickerList.length?filePickerList.map(f=>{const on=pickedFile&&pickedFile.file_id===f.file_id;return `<label class="picker-row${on?' on':''}"><input type="radio" name="fpPick" ${on?'checked':''} onchange="pickFile(${f.file_id})"><span class="picker-type">${esc(fileTypeLabel(f.file_type))}</span><div class="grow"><strong>${esc(f.original_name)}</strong><small>${fmt(f.upload_time)} · ${sizeText(f.file_size)}</small></div></label>`}).join(''):'<div class="empty">还没有上传过文件，请先在上方选择文件上传</div>'}
function pickFile(id){pickedFile=filePickerList.find(x=>x.file_id===id)||null;renderFilePicker()}
async function submitFileUpload(){const input=document.getElementById('fpFile');if(!input||!input.files[0])return showToast('请先选择要上传的文件');const d=new FormData();d.append('file',input.files[0]);d.append('visibility',document.getElementById('fpVisibility').value);const desc=document.getElementById('fpDesc').value.trim();if(desc)d.append('description',desc);showToast('正在上传…');const r=await API.uploadFile(d);if(r.status!==201)return showToast(r.data.msg||'上传失败');pickedFile=r.data.file;const list=await API.myFiles();filePickerList=list.status===200?list.data.files:[pickedFile,...filePickerList];input.value='';document.getElementById('fpDesc').value='';renderFilePicker();showToast('上传成功：'+pickedFile.original_name)}
function confirmFilePick(){if(!pickedFile)return showToast('请先选择或上传一个文件');const cb=filePickerCallback;filePickerCallback=null;closeModal();if(cb)cb(pickedFile)}
function openActivityForm(){openModal('新建活动项目',`<div class="modal-form"><label>活动名称<input id="fTitle" placeholder="例：周一升旗仪式"></label><label>活动类型<select id="fType"><option>升旗</option><option>出旗</option><option>训练</option><option>其他</option></select></label><label>活动开始<input id="fStart" type="datetime-local"></label><label>活动结束<input id="fEnd" type="datetime-local"></label><label>签到开始<input id="fCheckinStart" type="datetime-local"></label><label>签到截止<input id="fCheckinEnd" type="datetime-local"></label><label>参与积分<input id="fPoints" type="number" min="0" max="1000" value="10"></label><label>活动地点<input id="fLocation" placeholder="例：学校东区田径场"></label><label class="wide upload-field">活动封面图片<input id="fCover" type="file" accept="image/jpeg,image/png,image/webp,image/gif"><small>支持 JPG、PNG、WebP、GIF，图片将在活动目录卡片中显示</small></label><label class="wide">任务说明<textarea id="fDesc" rows="3"></textarea></label></div>${formActions('submitActivity()','创建项目')}`,'ACTIVITY')}
async function submitActivity(){const d=new FormData();d.append('title',fTitle.value.trim());d.append('activity_type',fType.value);d.append('start_time',fStart.value);if(fEnd.value)d.append('end_time',fEnd.value);if(fCheckinStart.value)d.append('checkin_start',fCheckinStart.value);if(fCheckinEnd.value)d.append('checkin_end',fCheckinEnd.value);d.append('participation_points',fPoints.value);d.append('location',fLocation.value.trim());d.append('description',fDesc.value.trim());if(fCover.files[0])d.append('cover',fCover.files[0]);const r=await API.createActivity(d);if(r.status===201){closeModal();showToast('活动项目已创建');loadActivities()}else showToast(r.data.msg||'创建失败')}
async function ensureMembers(){if(allMembers.length)return;const r=await API.members();if(r.status===200)allMembers=r.data.members}
async function openActivity(id){await ensureMembers();const r=await API.activity(id);if(r.status!==200)return showToast(r.data.msg);const a=r.data.activity,now=new Date(),started=now>=new Date(a.start_time),ended=['已完成','已终止'].includes(a.status)||(a.end_time&&now>=new Date(a.end_time)),
/* 与后端 _can_manage_activity 严格对齐：队长、本项目主教官、或教官部授权人员。
   原先写成 isManager()||created_by===自己，会让后勤部部长、综合办公室部长看到
   考勤评分表单，一点保存就被后端 403 打回；项目移交之后原创建者也不再有权。 */
canManage=hasRole('captain')||hasRole('admin')||a.lead_instructor_id===currentUser.user_id||canEditDepartment('教官部');const opts=allMembers.map(m=>`<option value="${m.user_id}">${esc(m.real_name||m.username)} · ${esc(m.department||'未分部')}</option>`).join('');const participantRows=a.participants.length?a.participants.map(p=>`<div class="usage-row"><div class="icon">${esc(p.name).charAt(0)}</div><div class="grow"><h4>${esc(p.name)}</h4><p>${esc(p.attendance_status)} · ${p.checkin_method?esc(p.checkin_method)+' · ':''}${p.checked_at?fmtFull(p.checked_at):'未打卡'} · ${p.score??'未评分'} 分${p.points_awarded?' · +'+p.points_awarded+'积分':''}</p></div></div>`).join(''):'<div class="empty">暂未登记参与社员</div>';const mediaRows=(r.data.media||[]).map(m=>`<div class="review-row"><div class="grow"><h4>${esc(m.file?.original_name||'素材文件')}</h4><p>${esc(m.submitter_name)} · ${fmtFull(m.submitted_at)}${m.review_comment?' · '+esc(m.review_comment):''}</p></div><span class="tag ${m.review_status==='待审阅'?'red':''}">${esc(m.review_status)}</span></div>`).join('');const mediaSubmit=a.status==='已终止'?'':`<button class="small-btn media-submit-btn" onclick="openMediaSubmit(${id})">＋ 提交活动素材</button>`;const mediaBlock=`<h4>活动素材</h4><div class="review-list">${mediaRows||'<div class="empty">还没有提交素材</div>'}</div>${mediaSubmit}`;let record='';if(ended){const rr=await API.activityRecord(id);if(rr.status===200){const x=rr.data;record=`<div class="final-record"><h4>活动结束记录</h4><div class="record-stats"><span>参与名单 <b>${x.participants.length} 人</b></span><span>平均评分 <b>${x.average_score??'—'}</b></span><span>已发积分 <b>${x.total_points_awarded}</b></span></div><p>${Object.entries(x.attendance_summary).map(([k,v])=>`${esc(k)} ${v}人`).join(' · ')||'暂无考勤记录'}</p></div>`}}const manage=canManage?`<div class="manage-block"><h4>考勤与考评管理</h4><div class="modal-form"><label>社员<select id="pUser">${opts}</select></label><label>考勤<select id="pAttend"><option>已到</option><option>迟到</option><option>请假</option><option>缺勤</option></select></label><label>表现评分<input id="pScore" type="number" min="0" max="100" value="90"></label><label>表现评语<input id="pComment" placeholder="动作、纪律、协作等"></label></div><button class="small-btn" onclick="saveParticipant(${id})">记录考勤与评分</button><hr><div class="modal-form"><label>移交活动主教官<select id="leadUser">${opts}</select></label><label>项目状态<select id="summaryStatus"><option ${a.status==='筹备中'?'selected':''}>筹备中</option><option ${a.status==='进行中'?'selected':''}>进行中</option><option ${a.status==='已完成'?'selected':''}>已完成</option></select></label><label class="wide">项目总结<textarea id="activitySummary" rows="4" placeholder="由活动主教官填写复盘总结">${esc(a.summary||'')}</textarea></label></div><div class="modal-foot">${!started&&a.status!=='已终止'?`<button class="small-btn" onclick="openEditActivity(${id})">编辑安排</button>`:''}${!['已完成','已终止'].includes(a.status)?`<button class="small-btn danger" onclick="terminateActivity(${id})">人为终止</button>`:''}<button class="small-btn" onclick="transferActivity(${id})">移交主教官</button><button class="btn primary" onclick="saveActivitySummary(${id})">保存总结</button></div></div>`:'';openModal(a.title,`<div class="panel-head"><span class="tag red">${esc(a.activity_type)} · ${esc(a.status)}</span><span>${fmtFull(a.start_time)} · ${esc(a.location||'地点待定')}</span></div><p>${esc(a.description||'暂无说明')}</p><div class="activity-rules"><span>签到：${fmtFull(a.checkin_start)} 至 ${fmtFull(a.checkin_end)}</span><b>有效参与 +${a.participation_points} 积分</b></div><button class="btn primary checkin-main" onclick="checkInActivity(${id})" ${ended?'disabled':''}>本人考勤打卡</button><h4>参与人员名单</h4><div class="review-list">${participantRows}</div>${mediaBlock}${record}${manage}`,'PROJECT DETAIL')}
async function checkInActivity(id){const r=await API.checkIn(id);showToast(r.data.msg||'打卡完成');if(r.status===200)openActivity(id)}
function openMediaSubmit(id){openFilePicker('提交活动素材',async f=>{const r=await API.submitMedia(id,{file_id:f.file_id});showToast(r.data.msg||'操作完成');if(r.status===201)openActivity(id)})}
async function openEditActivity(id){const a=allActivities.find(x=>x.activity_id===id)||(await API.activity(id)).data.activity;openModal('编辑活动安排',`<div class="modal-form"><label>活动名称<input id="editTitle" value="${esc(a.title)}"></label><label>活动类型<select id="editType"><option ${a.activity_type==='升旗'?'selected':''}>升旗</option><option ${a.activity_type==='出旗'?'selected':''}>出旗</option><option ${a.activity_type==='训练'?'selected':''}>训练</option><option ${a.activity_type==='其他'?'selected':''}>其他</option></select></label><label>活动开始<input id="editStart" type="datetime-local" value="${localInput(a.start_time)}"></label><label>活动结束<input id="editEnd" type="datetime-local" value="${localInput(a.end_time)}"></label><label>签到开始<input id="editCheckinStart" type="datetime-local" value="${localInput(a.checkin_start)}"></label><label>签到截止<input id="editCheckinEnd" type="datetime-local" value="${localInput(a.checkin_end)}"></label><label>参与积分<input id="editPoints" type="number" min="0" max="1000" value="${a.participation_points}"></label><label>地点<input id="editLocation" value="${esc(a.location||'')}"></label><label class="wide">任务说明<textarea id="editDesc" rows="3">${esc(a.description||'')}</textarea></label></div>${formActions(`submitActivityEdit(${id})`,'保存修改')}`,'EDIT ACTIVITY')}
async function submitActivityEdit(id){const r=await API.editActivity(id,{title:editTitle.value.trim(),activity_type:editType.value,start_time:editStart.value,end_time:editEnd.value||null,checkin_start:editCheckinStart.value,checkin_end:editCheckinEnd.value,participation_points:+editPoints.value,location:editLocation.value.trim(),description:editDesc.value.trim()});showToast(r.data.msg||'操作完成');if(r.status===200){closeModal();loadActivities()}}
async function terminateActivity(id){const reason=prompt('请输入人为终止原因（将永久保留在项目记录中）：');if(!reason)return;const r=await API.terminateActivity(id,{reason});showToast(r.data.msg||'操作完成');if(r.status===200){closeModal();loadActivities()}}
async function saveParticipant(id){const r=await API.updateParticipant(id,{user_id:+pUser.value,attendance_status:pAttend.value,score:+pScore.value,performance_comment:pComment.value});showToast(r.data.msg||'操作完成');if(r.status===200)openActivity(id)}
async function transferActivity(id){const r=await API.transferActivity(id,{lead_instructor_id:+leadUser.value});showToast(r.data.msg||'操作完成');if(r.status===200){closeModal();loadActivities()}}
async function saveActivitySummary(id){const r=await API.saveSummary(id,{summary:activitySummary.value,status:summaryStatus.value});showToast(r.data.msg||'操作完成');if(r.status===200){closeModal();loadActivities()}}
async function loadEquipment(){const [e,u,c]=await Promise.all([API.equipment(),API.usages(),API.equipmentCategories()]);if(e.status!==200)return showToast(e.data.msg);equipmentCategories=c.data?.categories||[];equipmentCategoriesFlat=c.data?.flat_categories||[];renderEquipmentCategories();allEquipment=e.data.equipment||[];const rows=allEquipment;const total=rows.reduce((s,x)=>s+x.total_quantity,0),free=rows.reduce((s,x)=>s+x.available_quantity,0);document.getElementById('equipmentStats').innerHTML=`<div class="mini-stat"><strong>${equipmentCategoriesFlat.length}</strong><span>分类节点</span></div><div class="mini-stat"><strong>${total}</strong><span>设备总数</span></div><div class="mini-stat"><strong>${free}</strong><span>当前可用</span></div><div class="mini-stat"><strong>${total-free}</strong><span>正在占用</span></div>`;document.getElementById('equipmentBody').innerHTML=rows.length?rows.map(x=>`<tr><td>${x.cover_url?`<img class="equipment-thumb" src="${esc(x.cover_url)}" alt="${esc(x.equipment_name)}">`:`<div class="equipment-thumb placeholder">箱</div>`}</td><td>${esc(x.asset_code)}</td><td><strong>${esc(x.equipment_name)}</strong></td><td>${esc(x.category)}</td><td><div class="stock"><b>${x.available_quantity}/${x.total_quantity}</b><div class="stock-bar"><i style="width:${x.total_quantity?x.available_quantity/x.total_quantity*100:0}%"></i></div></div></td><td>${esc(x.storage_location||'—')}</td><td><span class="tag ${x.status!=='正常'?'orange':(x.is_occupied?'red':'')}">${x.status!=='正常'?esc(x.status):(x.is_occupied?'已占满':esc(x.status))}</span></td><td><div class="row-actions"><button class="small-btn" ${x.available_quantity&&x.status==='正常'?'':'disabled'} onclick="openBorrow(${x.equipment_id})">领用</button><button class="small-btn manager-only logistics-only" onclick="openEquipmentForm(${x.equipment_id})">编辑</button><button class="small-btn danger manager-only logistics-only" onclick="removeEquipment(${x.equipment_id})">删除</button></div></td></tr>`).join(''):'<tr><td colspan="8" class="empty">暂无设备</td></tr>';const uses=u.data?.usages||[];document.getElementById('usageList').innerHTML=uses.length?uses.map(x=>`<div class="usage-row"><div class="icon">箱</div><div class="grow"><h4>${esc(x.equipment_name)} × ${x.quantity}</h4><p>${esc(x.user_name)} · ${fmt(x.borrowed_at)}领用 · 预计 ${fmt(x.expected_return_at)}归还</p></div><span class="tag orange">${esc(x.status)}</span><button class="small-btn" onclick="returnEquipment(${x.usage_id})">归还</button></div>`).join(''):'<div class="empty">当前没有设备占用</div>';renderAccess()}
function renderEquipmentCategories(){const tree=document.getElementById('equipmentCategoryTree');if(!tree)return;const branch=(nodes,depth=0)=>nodes.map(x=>`<div class="category-node" style="--depth:${depth}"><div><span class="category-folder">${x.children?.length?'▾':'•'}</span><strong>${esc(x.category_name)}</strong><small>${x.equipment_count} 项设备</small></div><div class="category-actions manager-only logistics-only"><button onclick="openCategoryForm(${x.category_id})">＋ 子分类</button><button onclick="deleteEquipmentCategory(${x.category_id})">删除</button></div></div>${branch(x.children||[],depth+1)}`).join('');tree.innerHTML=equipmentCategories.length?branch(equipmentCategories):'<div class="empty">暂无设备分类</div>';renderAccess()}
function openCategoryForm(parentId=''){const parentOptions=equipmentCategoriesFlat.map(x=>`<option value="${x.category_id}" ${String(parentId)===String(x.category_id)?'selected':''}>${esc(x.full_name)}</option>`).join('');openModal('新建设备分类',`<div class="modal-form"><label>分类名称<input id="cName" placeholder="例：旗帜类"></label><label>父分类<select id="cParent"><option value="">作为一级分类</option>${parentOptions}</select></label><label>排序值<input id="cOrder" type="number" value="0"></label><label class="wide">分类说明<textarea id="cDesc"></textarea></label></div>${formActions('submitEquipmentCategory()','创建分类')}`,'CATEGORY')}
async function submitEquipmentCategory(){const r=await API.createEquipmentCategory({category_name:cName.value.trim(),parent_id:cParent.value?+cParent.value:null,sort_order:+cOrder.value,description:cDesc.value.trim()});showToast(r.data.msg||'操作完成');if(r.status===201){closeModal();loadEquipment()}}
async function deleteEquipmentCategory(id){if(!confirm('确定删除这个分类吗？仅空分类可以删除。'))return;const r=await API.deleteEquipmentCategory(id);showToast(r.data.msg||'操作完成');if(r.status===200)loadEquipment()}
let editingEquipmentId=null;
async function openEquipmentForm(id){editingEquipmentId=id||null;if(!equipmentCategoriesFlat.length){const r=await API.equipmentCategories();equipmentCategoriesFlat=r.data.flat_categories||[]}const eq=editingEquipmentId?allEquipment.find(x=>x.equipment_id===editingEquipmentId):null;const opts=equipmentCategoriesFlat.map(x=>`<option value="${x.category_id}" ${eq&&eq.category_id===x.category_id?'selected':''}>${esc(x.full_name)}</option>`).join('');const statuses=['正常','维修中','报废','已遗失'].map(s=>`<option ${eq&&eq.status===s?'selected':''}>${s}</option>`).join('');openModal(eq?'编辑设备信息':'登记新设备',`<div class="modal-form"><label>资产编号<input id="eCode" value="${esc(eq?eq.asset_code:'')}" placeholder="例：YZZB-025"></label><label>设备名称<input id="eName" value="${esc(eq?eq.equipment_name:'')}"></label><label>设备分类<select id="eCategory">${opts}</select></label><label>数量<input id="eQty" type="number" min="1" value="${eq?eq.total_quantity:1}"></label><label>设备状态<select id="eStatus">${statuses}</select></label><label class="wide">存放位置<input id="eLocation" value="${esc(eq&&eq.storage_location?eq.storage_location:'')}"></label><label class="wide upload-field">设备图片<input id="eCover" type="file" accept="image/jpeg,image/png,image/webp,image/gif"><small>${eq?'留空则沿用现有图片；选择新图片会替换并清理旧文件':'图片将在设备目录和台账中显示'}</small></label><label class="wide">备注<textarea id="eNotes">${esc(eq&&eq.notes?eq.notes:'')}</textarea></label></div>${eq?`<p class="form-note">当前在外未归还 ${eq.occupied_quantity} 件，总量不能少于该数量；${eq.status==='正常'?'':'该状态下不可领用。'}</p>`:''}${formActions('submitEquipment()',eq?'保存修改':'确认登记')}`,'EQUIPMENT')}
async function submitEquipment(){const d=new FormData();d.append('asset_code',eCode.value.trim());d.append('equipment_name',eName.value.trim());d.append('category_id',eCategory.value);d.append('total_quantity',eQty.value);d.append('status',eStatus.value);d.append('storage_location',eLocation.value.trim());d.append('notes',eNotes.value.trim());if(eCover.files[0])d.append('cover',eCover.files[0]);const r=editingEquipmentId?await API.updateEquipment(editingEquipmentId,d):await API.createEquipment(d);showToast(r.data.msg||'操作完成');if(r.status===200||r.status===201){closeModal();loadEquipment()}}
async function removeEquipment(id){const eq=allEquipment.find(x=>x.equipment_id===id);if(!confirm(`确定删除「${eq?eq.equipment_name:'该设备'}」吗？\n\n已有领用历史的设备不能删除，需要保留台账，请把状态改为「报废」。`))return;const r=await API.deleteEquipment(id);showToast(r.data.msg||'操作完成');if(r.status===200)loadEquipment()}
/* 设备名不再拼进 onclick 字符串：原先用 '${esc(name)}' 内联，设备名里带单引号时
   HTML 实体解码回来会截断 JS 字符串，既有语法错误风险也是注入口。改成只传 id。 */
function openBorrow(id){const eq=allEquipment.find(x=>x.equipment_id===id);if(!eq)return;const free=eq.available_quantity;openModal('领用 '+eq.equipment_name,`<div class="modal-form"><label>领用数量<input id="bQty" type="number" min="1" max="${free}" value="1"></label><label>预计归还<input id="bReturn" type="datetime-local"></label><label class="wide">用途说明<textarea id="bNotes" placeholder="请填写活动或训练用途"></textarea></label></div><p>当前可用：<b>${free}</b> 件，超出数量时系统将阻止占用。</p>${formActions(`submitBorrow(${id})`,'确认领用')}`,'BORROW')}
async function submitBorrow(id){const r=await API.borrow(id,{quantity:+bQty.value,expected_return_at:bReturn.value||null,notes:bNotes.value});showToast(r.data.msg||'操作完成');if(r.status===201){closeModal();loadEquipment()}}
async function returnEquipment(id){const r=await API.returnEquipment(id);showToast(r.data.msg||'操作完成');if(r.status===200)loadEquipment()}
async function loadOffice(){const [s,a,m]=await Promise.all([API.socials(),API.archives(),API.mediaQueue()]);document.getElementById('socialList').innerHTML=(allSocials=s.data.accounts||[]).map(x=>`<div class="social-item"><div class="social-icon">${esc(x.icon||x.platform).charAt(0)}</div><div class="grow"><strong>${esc(x.platform)}</strong><small>${esc(x.account_name)}</small></div><a href="${esc(x.link_url)}" target="_blank" rel="noopener">访问 ↗</a><div class="row-actions manager-only office-only"><button class="small-btn" onclick="openSocialForm(${x.account_id})">编辑</button><button class="small-btn danger" onclick="removeSocial(${x.account_id})">删除</button></div></div>`).join('')||'<div class="empty">暂无社媒账号</div>';document.getElementById('archiveBody').innerHTML=(allArchives=a.data.archives||[]).map(x=>`<tr><td><strong>${esc(x.title)}</strong></td><td>${esc(x.archive_type)}</td><td>${esc(x.owner_name)}</td><td>${fmt(x.archived_at)}</td><td>${x.file?`<a class="file-link" href="${API.fileUrl(x.file.file_id,'download')}">${esc(x.file.original_name)} ↓</a>`:'—'}</td><td><div class="row-actions"><button class="small-btn manager-only office-only" onclick="openArchiveForm(${x.archive_id})">编辑</button><button class="small-btn danger manager-only office-only" onclick="removeArchive(${x.archive_id})">删除</button></div></td></tr>`).join('')||'<tr><td colspan="6" class="empty">暂无档案</td></tr>';const media=m.data.media||[];const pending=media.filter(x=>x.review_status==='待审阅').length;document.getElementById('pendingBadge').textContent=pending+' 项待审';document.getElementById('mediaQueue').innerHTML=media.length?media.slice(0,8).map(x=>`<div class="review-row"><div class="grow"><h4>${esc(x.activity_title)}</h4><p>${x.file?`<a class="file-link" href="${API.fileUrl(x.file.file_id,'download')}">${esc(x.file.original_name)} ↓</a>`:'素材文件'} · ${esc(x.submitter_name)}</p></div><span class="tag ${x.review_status==='待审阅'?'red':''}">${esc(x.review_status)}</span>${x.review_status==='待审阅'?`<button class="small-btn office-only" onclick="reviewMedia(${x.media_id})">审阅</button>`:''}</div>`).join(''):'<div class="empty">暂无待审素材</div>';renderAccess()}
let editingSocialId=null;
function openSocialForm(id){editingSocialId=id||null;const s=editingSocialId?allSocials.find(x=>x.account_id===editingSocialId):null;openModal(s?'编辑社交媒体账号':'添加社交媒体账号',`<div class="modal-form"><label>平台名称<input id="sPlatform" value="${esc(s?s.platform:'')}" placeholder="例：微信公众号"></label><label>账号名称<input id="sName" value="${esc(s?s.account_name:'')}"></label><label class="wide">主页链接<input id="sUrl" type="url" value="${esc(s?s.link_url:'')}" placeholder="https://"></label><label class="wide">图标文字<input id="sIcon" value="${esc(s&&s.icon?s.icon:'')}" placeholder="留空则自动取平台名首字"></label></div>${formActions('submitSocial()',s?'保存修改':'确认添加')}`,'SOCIAL MEDIA')}
async function submitSocial(){const platform=sPlatform.value.trim();const body={platform,account_name:sName.value.trim(),link_url:sUrl.value.trim(),icon:document.getElementById('sIcon').value.trim()||platform.charAt(0)};const r=editingSocialId?await API.updateSocial(editingSocialId,body):await API.createSocial(body);showToast(r.data.msg||'操作完成');if(r.status===200||r.status===201){closeModal();loadOffice()}}
async function removeSocial(id){const s=allSocials.find(x=>x.account_id===id);if(!confirm(`确定删除「${s?s.platform:''} · ${s?s.account_name:''}」这个社媒账号吗？`))return;const r=await API.deleteSocial(id);showToast(r.data.msg||'操作完成');if(r.status===200)loadOffice()}
let archiveDraft=null;
function openArchiveForm(id){const row=id?(allArchives.find(x=>x.archive_id===id)||null):null;archiveDraft=row?{archive_id:row.archive_id,title:row.title,type:row.archive_type,desc:row.description||'',file:row.file?{file_id:row.file.file_id,original_name:row.file.original_name}:null}:{archive_id:null,title:'',type:'制度文件',desc:'',file:null};renderArchiveForm()}
function renderArchiveForm(){const d=archiveDraft;openModal(d.archive_id?'编辑档案信息':'新建文件归档',`<div class="modal-form"><label>档案标题<input id="aTitle" value="${esc(d.title)}"></label><label>档案类型<select id="aType">${['制度文件','活动方案','会议纪要','宣传材料','其他'].map(t=>`<option ${d.type===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="wide">关联文件<button type="button" class="small-btn" onclick="pickArchiveFile()">${d.file?'重新选择文件':'选择或上传文件'}</button><span class="form-note">${d.file?esc(d.file.original_name):'尚未选择文件，请先选择或上传'}</span></label><label class="wide">档案说明<textarea id="aDesc" rows="3">${esc(d.desc)}</textarea></label></div>${formActions('submitArchive()',d.archive_id?'保存修改':'确认归档')}`,'ARCHIVE')}
function keepArchiveDraft(){const t=document.getElementById('aTitle'),y=document.getElementById('aType'),s=document.getElementById('aDesc');if(t)archiveDraft.title=t.value;if(y)archiveDraft.type=y.value;if(s)archiveDraft.desc=s.value}
function pickArchiveFile(){keepArchiveDraft();openFilePicker('选择归档文件',f=>{archiveDraft.file=f;renderArchiveForm()})}
async function submitArchive(){keepArchiveDraft();const d=archiveDraft;if(!d.title.trim())return showToast('请填写档案标题');if(!d.file)return showToast('请先选择需要归档的文件');const body={title:d.title.trim(),archive_type:d.type,file_id:d.file.file_id,description:d.desc.trim()};const r=d.archive_id?await API.updateArchive(d.archive_id,body):await API.createArchive(body);showToast(r.data.msg||'操作完成');if(r.status===200||r.status===201){closeModal();loadOffice()}}
async function removeArchive(id){const row=allArchives.find(x=>x.archive_id===id);if(!confirm(`确定删除档案「${row?row.title:''}」吗？\n\n只解除归档关系，文件库里的原始文件会保留。`))return;const r=await API.deleteArchive(id);showToast(r.data.msg||'操作完成');if(r.status===200)loadOffice()}
function reviewMedia(id){openModal('审阅活动素材',`<div class="modal-form"><label>审阅结果<select id="rStatus"><option>已通过</option><option>需修改</option><option>已归档</option></select></label><label class="wide">审阅意见<textarea id="rComment"></textarea></label></div>${formActions(`submitReview(${id})`,'提交结果')}`,'MEDIA REVIEW')}
async function submitReview(id){const r=await API.reviewMedia(id,{review_status:rStatus.value,review_comment:rComment.value});showToast(r.data.msg||'操作完成');if(r.status===200){closeModal();loadOffice()}}
async function loadForum(){const r=await API.forumPosts();if(r.status!==200)return showToast(r.data.msg||'论坛加载失败');forumPosts.innerHTML=r.data.posts.length?r.data.posts.map(p=>`<article class="forum-post"><header><div class="forum-avatar">${esc(p.author_name).charAt(0)}</div><div><strong>${esc(p.author_name)}</strong><small>@${esc(p.author_username)} · ${fmtFull(p.created_at)}</small></div>${p.author_id===currentUser.user_id||hasRole('captain')?`<button onclick="removePost(${p.post_id})">删除</button>`:''}</header><h3>${esc(p.title)}</h3><p>${esc(p.content)}</p><div class="forum-comments">${p.comments.map(c=>`<div><b>${esc(c.author_name)}</b><span>${esc(c.content)}</span><time>${fmtFull(c.created_at)}</time></div>`).join('')||'<small>暂无回复</small>'}</div><div class="reply-box"><input id="reply${p.post_id}" placeholder="实名回复这条帖子"><button onclick="replyPost(${p.post_id})">回复</button></div></article>`).join(''):'<div class="empty">论坛还没有帖子，来发布第一条吧</div>'}
function openPostForm(){openModal('发布实名帖子',`<div class="modal-form"><label class="wide">标题<input id="postTitle" maxlength="120"></label><label class="wide">内容<textarea id="postContent" rows="6" maxlength="5000"></textarea></label></div><p class="form-note">帖子将显示你的账户姓名和用户名。</p>${formActions('submitPost()','发布')}`,'MEMBER FORUM')}
async function submitPost(){const r=await API.createPost({title:postTitle.value.trim(),content:postContent.value.trim()});showToast(r.data.msg||'发布完成');if(r.status===201){closeModal();loadForum()}}
async function replyPost(id){const input=document.getElementById('reply'+id),r=await API.createComment(id,{content:input.value.trim()});showToast(r.data.msg||'回复完成');if(r.status===201)loadForum()}
async function removePost(id){if(!confirm('确定删除这条帖子吗？'))return;const r=await API.deletePost(id);showToast(r.data.msg||'操作完成');if(r.status===200)loadForum()}
async function loadGovernance(){const r=await API.governance();if(r.status!==200)return showToast(r.data.msg||'审批数据加载失败');const d=r.data;membershipRequests.innerHTML=d.membership_requests.length?d.membership_requests.map(x=>`<div class="approval-row"><div><b>${esc(x.request_type)} · ${esc(x.user_name)}</b><small>@${esc(x.username)} · ${esc(x.student_no||'无学号')} · ${fmtFull(x.created_at)}</small><p>${esc(x.reason||'未填写说明')}</p></div><div><button onclick="reviewMembership(${x.request_id},true)">通过</button><button class="danger" onclick="reviewMembership(${x.request_id},false)">驳回</button></div></div>`).join(''):'<div class="empty">暂无待审核入队或注销申请</div>';departmentApplications.innerHTML=d.department_applications.length?d.department_applications.map(x=>{const canReview=hasRole('captain')||(hasRole('minister')&&currentUser.department_id===x.department_id);return `<div class="approval-row"><div><b>${esc(x.user_name)} → ${esc(x.department_name)}</b><small>队长：${x.captain_approved===true?'已通过':x.captain_approved===false?'已驳回':'待审核'} · 部长：${x.minister_approved===true?'已通过':x.minister_approved===false?'已驳回':'待审核'}</small><p>${esc(x.reason||'未填写说明')} · ${esc(x.status)}</p></div>${canReview&&x.status==='待审核'?`<div><button onclick="reviewDepartment(${x.application_id},true)">通过</button><button class="danger" onclick="reviewDepartment(${x.application_id},false)">驳回</button></div>`:''}</div>`}).join(''):'<div class="empty">暂无部门申请</div>';temporaryGrants.innerHTML=d.grants.length?d.grants.map(x=>`<div class="approval-row"><div><b>${esc(x.user_name)} · ${esc(x.department_name)}</b><small>${x.active?'生效中':'已失效'} · 截止 ${fmtFull(x.expires_at)}</small><p>${esc(x.reason||'临时协助')}</p></div>${x.active&&(hasRole('captain')||hasRole('minister'))?`<button class="danger" onclick="revokeGrant(${x.grant_id})">撤销</button>`:''}</div>`).join(''):'<div class="empty">暂无临时权限</div>';leadershipTransfers.innerHTML=d.transfers.length?d.transfers.map(x=>`<div class="approval-row"><div><b>${esc(x.role_label)}交接${x.department_name?' · '+esc(x.department_name):''}</b><small>${esc(x.from_user_name)} → ${esc(x.to_user_name)} · ${esc(x.status)}</small><p>${esc(x.note||'未填写说明')} · ${fmtFull(x.created_at)}</p></div>${x.to_user_id===currentUser.user_id&&x.status==='待确认'?`<div><button onclick="respondTransfer(${x.transfer_id},true)">接受</button><button class="danger" onclick="respondTransfer(${x.transfer_id},false)">拒绝</button></div>`:''}</div>`).join(''):'<div class="empty">暂无职务交接记录</div>';renderAccess()}
async function reviewMembership(id,approved){const r=await API.reviewMembership(id,{approved});showToast(r.data.msg||'审核完成');if(r.status===200)loadGovernance()}
async function reviewDepartment(id,approved){const r=await API.reviewDepartment(id,{approved});showToast(r.data.msg||'审核完成');if(r.status===200)loadGovernance()}
async function openAccountForm(){if(!departments.length){const r=await API.departments();departments=r.data.departments||[]}const options=departments.map(x=>`<option value="${x.department_id}">${esc(x.department_name)}</option>`).join('');openModal('队长创建账户',`<div class="modal-form"><label>用户名<input id="newUsername"></label><label>真实姓名<input id="newRealName"></label><label>电子邮箱<input id="newEmail" type="email"></label><label>学号<input id="newStudentNo"></label><label>初始密码<input id="newPassword" type="password" value="Member@123"></label><label>账户身份<select id="newRole"><option value="member">普通社员</option><option value="minister">部长</option></select></label><label class="wide">所属部门<select id="newDepartment"><option value="">暂不加入部门</option>${options}</select></label></div>${formActions('submitAccount()','创建账户')}`,'ACCOUNT')}
async function submitAccount(){const r=await API.createAccount({username:newUsername.value.trim(),real_name:newRealName.value.trim(),email:newEmail.value.trim(),student_no:newStudentNo.value.trim(),password:newPassword.value,role_name:newRole.value,department_id:newDepartment.value?+newDepartment.value:null});showToast(r.data.msg||'创建完成');if(r.status===201){closeModal();loadGovernance();allMembers=[]}}
async function removeAccount(id){if(!confirm('账户将被注销并禁止登录，历史记录会保留。确定继续吗？'))return;const r=await API.deleteAccount(id,{reason:'队长后台注销'});showToast(r.data.msg||'操作完成');if(r.status===200)loadMembers()}
async function openGrantForm(){await ensureMembers();if(!departments.length){const r=await API.departments();departments=r.data.departments||[]}const allowed=hasRole('captain')?allMembers:allMembers.filter(x=>x.department_id===currentUser.department_id);const userOpts=allowed.filter(x=>!x.roles.includes('captain')).map(x=>`<option value="${x.user_id}">${esc(x.real_name||x.username)} · ${esc(x.department||'未分部')}</option>`).join('');const deptOpts=(hasRole('captain')?departments:departments.filter(x=>x.department_id===currentUser.department_id)).map(x=>`<option value="${x.department_id}">${esc(x.department_name)}</option>`).join('');const expiry=new Date();expiry.setDate(expiry.getDate()+7);openModal('授予临时后台权限',`<div class="modal-form"><label>目标社员<select id="grantUser">${userOpts}</select></label><label>授权部门<select id="grantDepartment">${deptOpts}</select></label><label class="wide">权限截止<input id="grantExpiry" type="datetime-local" value="${localInput(expiry)}"></label><label class="wide">授权原因<textarea id="grantReason" rows="3"></textarea></label></div>${formActions('submitGrant()','确认授权')}`,'TEMPORARY ACCESS')}
async function submitGrant(){const r=await API.createGrant({user_id:+grantUser.value,department_id:+grantDepartment.value,expires_at:grantExpiry.value,reason:grantReason.value.trim()});showToast(r.data.msg||'授权完成');if(r.status===201){closeModal();loadGovernance()}}
async function revokeGrant(id){const r=await API.revokeGrant(id);showToast(r.data.msg||'操作完成');if(r.status===200)loadGovernance()}
async function openTransferForm(){await ensureMembers();const role=hasRole('captain')?'captain':'minister';const candidates=allMembers.filter(x=>x.user_id!==currentUser.user_id&&(role==='captain'||x.department_id===currentUser.department_id));const opts=candidates.map(x=>`<option value="${x.user_id}">${esc(x.real_name||x.username)} · ${esc(x.department||'未分部')}</option>`).join('');openModal('发起职务交接',`<div class="modal-form"><label>交接职务<input value="${role==='captain'?'队长':'部长'}" disabled></label><label>接任账户<select id="transferTarget">${opts}</select></label><label class="wide">交接说明<textarea id="transferNote" rows="3"></textarea></label></div>${formActions(`submitTransfer('${role}')`,'发起交接')}`,'HANDOVER')}
async function submitTransfer(role){const r=await API.proposeTransfer({role_name:role,to_user_id:+transferTarget.value,note:transferNote.value.trim()});showToast(r.data.msg||'交接申请已提交');if(r.status===201){closeModal();loadGovernance()}}
async function respondTransfer(id,accepted){const r=await API.respondTransfer(id,{accepted});showToast(r.data.msg||'处理完成');if(r.status===200){const p=await API.profile();if(p.status===200)currentUser=p.data.user;renderAccess();loadGovernance()}}
async function loadMembers(){const [m,d]=await Promise.all([API.members(),API.departments()]);if(m.status!==200)return;allMembers=m.data.members;departments=d.data.departments||[];document.getElementById('departmentSummary').innerHTML=departments.map(x=>`<div class="dept-box"><strong>${esc(x.department_name)}</strong><p>${esc(x.description)}</p><span>${x.member_count}</span> <small>名成员</small></div>`).join('');renderMembers()}
function renderMembers(){const q=(document.getElementById('memberSearch')?.value||'').toLowerCase();const rows=allMembers.filter(x=>[x.real_name,x.username,x.student_no,x.department].join(' ').toLowerCase().includes(q));document.getElementById('memberGrid').innerHTML=rows.map(x=>`<div class="member-card"><div class="member-avatar">${esc(x.real_name||x.username).charAt(0)}</div><div class="grow"><strong>${esc(x.real_name||x.username)}</strong><small>${esc(departmentLabel(x))} · ${(x.roles||[]).map(r=>roleNames[r]||r).join('/')}</small></div>${hasRole('captain')&&x.user_id!==currentUser.user_id&&!x.roles.includes('captain')?`<button class="member-delete" onclick="removeAccount(${x.user_id})">注销</button>`:''}</div>`).join('')||'<div class="empty">没有匹配成员</div>'}
async function loadProfile(){if(!currentUser)return;const name=currentUser.real_name||currentUser.username;profileSeal.textContent=name.charAt(0);profileName.textContent=name;profileRole.textContent=`${departmentLabel(currentUser)} · ${(currentUser.roles||[]).map(r=>roleNames[r]||r).join('/')}`;profileUsername.value=currentUser.username;profileRealName.value=currentUser.real_name||'';profileDepartment.value=departmentLabel(currentUser);profileEmail.value=currentUser.email||'';profilePhone.value=currentUser.phone||'';const r=await API.myPoints();if(r.status!==200)return;currentUser.points=r.data.points;profilePoints.textContent=r.data.points;pointTransactions.innerHTML=r.data.transactions.length?r.data.transactions.map(x=>`<div class="point-row"><div><strong>${esc(x.activity_title||x.reason)}</strong><small>${fmtFull(x.created_at)} · ${esc(x.reason)}</small></div><b>+${x.points}</b></div>`).join(''):'<div class="empty">暂无积分记录，参与并完成活动后即可获得积分</div>';renderAccess()}
async function saveProfile(){const r=await API.updateProfile({email:profileEmail.value.trim(),phone:profilePhone.value.trim()});if(r.status===200){currentUser=r.data.user;renderAccess();showToast('个人资料已保存')}else showToast(r.data.msg||'保存失败')}
function openPasswordForm(){openModal('修改登录密码',`<div class="modal-form"><label class="wide">当前密码<input id="pwOld" type="password" autocomplete="current-password"></label><label class="wide">新密码<input id="pwNew" type="password" placeholder="至少 6 位" autocomplete="new-password"></label><label class="wide">确认新密码<input id="pwNew2" type="password" autocomplete="new-password"></label></div><p class="form-note">修改后当前登录状态仍然有效，下次登录请使用新密码。</p>${formActions('submitPassword()','确认修改')}`,'SECURITY')}
async function submitPassword(){const next=document.getElementById('pwNew').value;if(next.length<6)return showToast('新密码不能少于 6 个字符');if(next!==document.getElementById('pwNew2').value)return showToast('两次输入的新密码不一致');const r=await API.changePassword({old_password:document.getElementById('pwOld').value,new_password:next});showToast(r.data.msg||'操作完成');if(r.status===200)closeModal()}
async function openDepartmentApplication(){const r=await API.departments();const opts=(r.data.departments||[]).map(x=>`<option value="${x.department_id}">${esc(x.department_name)}</option>`).join('');openModal('申请加入部门',`<div class="modal-form"><label class="wide">目标部门<select id="applyDepartment">${opts}</select></label><label class="wide">申请说明<textarea id="applyReason" rows="4"></textarea></label></div><p class="form-note">申请需要队长和目标部门部长分别通过后生效。</p>${formActions('submitDepartmentApplication()','提交双审')}`,'DEPARTMENT')}
async function submitDepartmentApplication(){const r=await API.applyDepartment({department_id:+applyDepartment.value,reason:applyReason.value.trim()});showToast(r.data.msg||'提交完成');if(r.status===201)closeModal()}
async function requestAccountDeactivation(){const reason=prompt('请输入注销原因。队长审核通过后账户将不能登录：');if(!reason)return;const r=await API.requestDeactivation({reason});showToast(r.data.msg||'提交完成');if(r.status===201){const p=await API.profile();if(p.status===200)currentUser=p.data.user}}
function updateClock(){const now=new Date(),clock=document.getElementById('timeClock'),date=document.getElementById('timeDate');if(clock)clock.textContent=now.toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false});if(date)date.textContent=now.toLocaleDateString('zh-CN',{year:'numeric',month:'long',day:'numeric',weekday:'long'})}
window.addEventListener('DOMContentLoaded',async()=>{document.getElementById('todayText').textContent=new Date().toLocaleDateString('zh-CN',{year:'numeric',month:'long',day:'numeric',weekday:'long'});updateClock();setInterval(updateClock,1000);document.getElementById('loginPassword').addEventListener('keydown',e=>{if(e.key==='Enter')doLogin()});await restoreSession();loadOverview()});
